import{_ as i,C as o,o as l,c as r,j as e,a as s,E as n,aB as c}from"./chunks/framework.BPloFSFy.js";const k=JSON.parse('{"title":"Example gallery","description":"","frontmatter":{},"headers":[],"relativePath":"examples.md","filePath":"examples.md","lastUpdated":null}'),d={name:"examples.md"};function h(p,a,m,u,g,b){const t=o("LeafCharts");return l(),r("div",null,[a[0]||(a[0]=e("h1",{id:"gallery",tabindex:"-1"},[s("Example gallery "),e("a",{class:"header-anchor",href:"#gallery","aria-label":'Permalink to "Example gallery {#gallery}"'},"​")],-1)),a[1]||(a[1]=e("p",null,[s("Small Julia examples, real model output. Change one input, inspect the response, then combine the components. Every curve on this page is computed by the runnable examples in "),e("a",{href:"https://github.com/RSFraLab/LeafPhotosynthesis.jl/tree/main/examples",target:"_blank",rel:"noreferrer"},[e("code",null,"examples/")]),s(" when the documentation is built; the browser only draws the saved Julia results. Switching precision selects a separate "),e("code",null,"Float32"),s(" or "),e("code",null,"Float64"),s(" run. Hover for values, or use the series controls, data tables, CSV downloads and PNG export below each plot.")],-1)),a[2]||(a[2]=e("div",{class:"leaf-app","data-leaf-app":"gallery"},[e("div",{class:"toolbar"},[e("label",{for:"gallery-precision"},"Numerical precision"),e("select",{id:"gallery-precision",class:"leaf-precision"},[e("option",{value:"Float64"},"Float64 · double"),e("option",{value:"Float32"},"Float32 · single")]),e("span",{id:"gallery-status",role:"status"},"Loading model output…")])],-1)),n(t),a[3]||(a[3]=c(`<h2 id="gallery-one-leaf" tabindex="-1">Evaluate one leaf <a class="header-anchor" href="#gallery-one-leaf" aria-label="Permalink to &quot;Evaluate one leaf {#gallery-one-leaf}&quot;">​</a></h2><p>Prescribe light, internal CO₂, and leaf temperature. <code>photosynthesize</code> returns carbon uptake and its component rates. Positive net assimilation means CO₂ uptake; negative values mean release.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/one_leaf.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete example</summary><pre><code data-source="one_leaf"></code></pre></details></div><p>Configuration stays in <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/setup/read_parameters.jl" target="_blank" rel="noreferrer">read_parameters.jl</a>; physical component assembly is visible in <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/setup/bonan_leaf.jl" target="_blank" rel="noreferrer">bonan_leaf.jl</a>. The main script calls the biophysics.</p><h2 id="gallery-bonan" tabindex="-1">Bonan 11.1: change one forcing at a time <a class="header-anchor" href="#gallery-bonan" aria-label="Permalink to &quot;Bonan 11.1: change one forcing at a time {#gallery-bonan}&quot;">​</a></h2><p>These three curves use Bonan&#39;s C3 parameterization. In each panel, only the horizontal-axis variable changes. The Rubisco- and electron-limited curves have respiration subtracted, so they can be compared with net assimilation.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/bonan_11_1.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete response-curve example</summary><pre><code data-source="bonan_11_1"></code></pre></details><p id="bonan-settings" class="settings"></p><div id="bonan-plots" class="plot-grid"></div></div><p>The CO₂ axis is internal CO₂ mole fraction, not ambient CO₂. It represents the biochemical site here, with no mesophyll diffusion solve. Numerical curves pass an independent high-precision equation check; comparison with executed upstream MATLAB output remains pending. See <a href="./bonan_exercises.html">scope and provenance</a>.</p><h2 id="gallery-equilibrium" tabindex="-1">Solve a leaf at equilibrium <a class="header-anchor" href="#gallery-equilibrium" aria-label="Permalink to &quot;Solve a leaf at equilibrium {#gallery-equilibrium}&quot;">​</a></h2><p>Now prescribe ambient CO₂ and solve assimilation, diffusion, and Ball–Berry stomata together. CO₂ at the leaf surface, intercellular space, and biochemical site can differ. Temperature and humidity remain prescribed.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/core_exchange.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete equilibrium example</summary><pre><code data-source="core_exchange"></code></pre></details><div id="equilibrium-values" class="results"></div></div><p>The derivatives describe the response to stomatal opening at fixed temperature. This is an illustrative component example, not a reproduction of Bonan 12.1. See <a href="./equilibrium_and_sensitivities.html">equations and assumptions</a>.</p><h2 id="gallery-stomata" tabindex="-1">Turn the light on, then off <a class="header-anchor" href="#gallery-stomata" aria-label="Permalink to &quot;Turn the light on, then off {#gallery-stomata}&quot;">​</a></h2><p>The prognostic model moves toward the current stomatal target. Its opening and closing time constants are separate parameters. Dashed lines show the fully coupled equilibrium for the same forcing, not the instantaneous target used in each prognostic step.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/stomatal_response.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete time-integration example</summary><pre><code data-source="stomatal_response"></code></pre></details><p id="stomatal-settings" class="settings"></p><div id="stomatal-plots" class="plot-grid"></div></div><p>Temperature, surface humidity, and transport conductances stay fixed. The example uses an explicit Euler step; it does not provide a general-purpose integrator. Net O₂ release and net CO₂ uptake overlap for this example&#39;s core stoichiometry and respiratory quotient of one. This equality is not a universal physiological constraint. See <a href="./core_exchange.html">oxygen budget and model limits</a>.</p><h2 id="gallery-turnover" tabindex="-1">Electron flow survives carbon cancellation <a class="header-anchor" href="#gallery-turnover" aria-label="Permalink to &quot;Electron flow survives carbon cancellation {#gallery-turnover}&quot;">​</a></h2><p>At the photorespiratory compensation point Γ*, carboxylation balances photorespiratory CO₂ release. Both processes still turn over, so realized linear electron flow remains positive even though pre-respiration carbon uptake is zero. Net uptake additionally subtracts respiration.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/biochemical_turnover.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete turnover example</summary><pre><code data-source="biochemical_turnover"></code></pre></details><div id="turnover-plots" class="plot-grid"></div></div><p>Light and temperature are fixed; CO₂ is prescribed at the biochemical site. The example uses signed C3 assimilation and computes turnover with oxygen exchange disabled. Alternative electron sinks, cyclic flow and fluorescence yield are not inferred. See <a href="./biochemical_turnover.html">equations and limits</a>.</p><h2 id="gallery-fluorescence" tabindex="-1">PSII excitation and fluorescence <a class="header-anchor" href="#gallery-fluorescence" aria-label="Permalink to &quot;PSII excitation and fluorescence {#gallery-fluorescence}&quot;">​</a></h2><p>Compare two replaceable quenching components using the same C3 model and the same absorbed photons. Rates and the low-light electron yield are explicitly compatible in this exercise; the earlier Bonan exercises retain their original values.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/fluorescence.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete fluorescence example</summary><pre><code data-source="fluorescence"></code></pre></details><div id="fluorescence-plots" class="plot-grid"></div></div><p>Temperature and biochemical-site CO₂ are prescribed. The empirical KN fit has PAM/PSI-contamination limitations; its PSII-only interpretation is an explicit approximation. There is no NPQ memory, PSI source or leaf optical escape here. Yield probabilities close an excitation budget, not a complete leaf energy budget. See <a href="./fluorescence.html">equations, parameter conventions and limits</a>.</p><h2 id="gallery-oxygen-response" tabindex="-1">Let the compensation point respond to O₂ <a class="header-anchor" href="#gallery-oxygen-response" aria-label="Permalink to &quot;Let the compensation point respond to O₂ {#gallery-oxygen-response}&quot;">​</a></h2><p>Rubisco competition and the photorespiratory compensation point must use the same oxygen level. Here Γ* scales with O₂ from a declared reference partial pressure. The prescribed-Γ* curve is a controlled comparison, incompatible with an oxygen sweep away from its calibration; it is not an alternative calibrated prediction.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/oxygen_response.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete oxygen-response example</summary><pre><code data-source="oxygen_response"></code></pre></details><div class="toolbar"><label>Leaf temperature <select id="oxygen-temperature" class="leaf-oxygen-temperature"><option value="1">Loading temperatures…</option></select></label></div><div id="oxygen-plots" class="plot-grid"></div></div><p>Ambient CO₂, light, surface humidity and diffusion conductances are prescribed. The A–Ci solve adjusts biochemical-site CO₂ and equilibrium stomata at each oxygen level. O₂ transport and anaerobic respiration are not solved. See <a href="./oxygen_response.html">equations, reference calibration and limits</a>.</p><h2 id="gallery-cytochrome-stress" tabindex="-1">Mechanistic versus empirical stress fluorescence <a class="header-anchor" href="#gallery-cytochrome-stress" aria-label="Permalink to &quot;Mechanistic versus empirical stress fluorescence {#gallery-cytochrome-stress}&quot;">​</a></h2><p>Compare empirical PSII quenching fits (van der Tol et al. 2014 Cotton and Drought <code>KN(x)</code>) against the coupled Cytochrome b₆f + PSII/PSI mechanics of Johnson &amp; Berry (2021), using shared Rubisco kinetics (<code>Vcmax25 = 60</code>) and aligned mid-PAR crossover capacities (FvCB <code>Jmax25 = 100.2, θ = 0.90</code> vs. Cytochrome <code>Vqmax25 = 195, SerialLimitation</code>).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/cytochrome_stress.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete Cytochrome stress-comparison example</summary><pre><code data-source="cytochrome_stress"></code></pre></details><div id="cytochrome-plots" class="plot-grid"></div></div><p>Under high-light stomatal closure, empirical Cotton <code>KN(x)</code> saturates early and predicts a slight fluorescence yield <em>increase</em>, requiring a separately fitted Drought parameter table. Johnson &amp; Berry&#39;s single mechanistic parameter set predicts strong feedback quenching under Rubisco/stomatal sink stress, PSI cyclic-flow rebalancing at moderate light, and opposite fluorescence signs for Rubisco vs. Cytochrome b₆f downregulation. Yields remain internal leaf emission probabilities before optical escape. See <a href="./cytochrome_fluorescence.html">biophysics, equations and stress regimes</a>.</p><h2 id="gallery-jb-benchmarks" tabindex="-1">Johnson &amp; Berry (2021) benchmarks <a class="header-anchor" href="#gallery-jb-benchmarks" aria-label="Permalink to &quot;Johnson &amp; Berry (2021) benchmarks {#gallery-jb-benchmarks}&quot;">​</a></h2><p>Reproduce four signature mechanisms from Johnson &amp; Berry (2021, <em>Photosynthesis Research</em> 148:101–136, Table 2 &amp; Fig. 8): PSII exciton sharing (<code>KU2</code>, Case 9), closed-form pointwise LHCII state transitions (<code>StateTransitionRule</code>, Case 10), coordinated Cytochrome b₆f + Rubisco capacity scaling (Case 12), and apparent leaf-chamber PAM fluorometry under PSI detector leakage (<code>PAMFluorescenceObserver</code>, Eqs. 38–42).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/johnson_berry_2021.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete Johnson &amp; Berry (2021) benchmark example</summary><pre><code data-source="johnson_berry_2021"></code></pre></details><div id="jb-benchmarks-plots" class="plot-grid"></div></div><p>With static antennae (Case 9), exciton sharing (<code>KU2 &gt; 0</code>) boosts PSII efficiency above PSI&#39;s capacity and forces low-light <code>KN &gt; 0</code>, damping the huge puddle (<code>KU2 = 0</code>) fluorescence spike. Closed-form state transitions (Case 10) instead migrate 17–22% of PSII cross-section to PSI, keeping <code>KN = 0</code> up to Rubisco saturation and restoring a moderate biphasic <code>ΦF2</code> peak while boosting light-limited assimilation. Coordinated capacity scaling (Case 12) shifts that peak in PAR and flips the sign of <code>∂ΦF2/∂capacity</code> between low and high light. In long-pass (&gt;700 nm) PAM detectors (<code>εF1/εF2 = 2</code>), PSI contributes ~39% of dark <code>Fo</code>, depressing apparent <code>1 − Fs/Fm′</code> and lake <code>1 − qL</code> while leaving puddle <code>qP</code> invariant when <code>KX1 = KP1</code>. See the <a href="/LeafPhotosynthesis.jl/dev/cytochrome_fluorescence.html#cytochrome-pam">closed-form derivations and PAM equations</a>.</p><h2 id="gallery-flexas-2002" tabindex="-1">Flexas et al. (2002) water-stress benchmark <a class="header-anchor" href="#gallery-flexas-2002" aria-label="Permalink to &quot;Flexas et al. (2002) water-stress benchmark {#gallery-flexas-2002}&quot;">​</a></h2><p>Test how every chlorophyll fluorescence formulation in <code>LeafPhotosynthesis.jl</code> reproduces, or structurally fails to reproduce, the grapevine water-stress experiment of Flexas et al. (2002, <em>Physiologia Plantarum</em> 114:231–240, Figs. 2, 3C &amp; 5): six drought stomatal conductances (<code>g = 150, 80, 62, 55, 39, 10 mmol H₂O m⁻² s⁻¹</code>), the <code>PPFD = 750</code> <code>Fs / Fo</code> vs. <code>g</code> inset, high-CO₂ / O₂-depleted reversion, and DTT xanthophyll inhibition.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/flexas_2002.jl</span></span></code></pre></div><p><strong><a href="/LeafPhotosynthesis.jl/dev/flexas_2002_explorer.html#flexas-explorer">Open the interactive Flexas et al. (2002) Figure 2 and SIF formulation explorer</a></strong> to switch across all six fluorescence formulations overlaid on all 55 digitized Figure 2 points, inspect single-conductance internal thylakoid states, and compare Julia RMSE scoreboards.</p><div class="leaf-app"><details class="source"><summary>Read the complete Flexas et al. (2002) water-stress benchmark</summary><pre><code data-source="flexas_2002"></code></pre></details><div id="flexas-plots" class="plot-grid"></div></div><p>Single-variable empirical <code>KN(x)</code> fits (van der Tol et al. 2014 Cotton and Drought) obey an invariant peak-height constraint (<code>max Fs/Fo ≈ 1.45–1.46</code> across all <code>g</code>), and Cotton <code>KN(x)</code> inverts the drought sign at high light. Coupling <code>CytochromeFluorescence</code> with a long-pass PSI weight in the PAM signal (<code>PAMFluorescenceObserver</code>, <code>εF1/εF2 = 2</code>, carried over from Johnson &amp; Berry&#39;s LI-6800 fit on <em>Populus fremontii</em>, giving dark <code>Fv/Fm = 0.821</code> vs. measured <code>0.80–0.83</code>) and an author-chosen non-stomatal drought schedule reproduces the progressive decline in peak <code>Fs / Fo</code>, a leftward shift in peak irradiance (the model&#39;s well-watered peak lies at higher irradiance than the digitized one), high-light sub-<code>Fo</code> quenching (<code>Fs / Fo &lt; 1</code>), curvilinear <code>Fs / Fo</code> vs. <code>g</code> inset, and Fig. 3C high-CO₂ reversion. The exciton transfer rate <code>KU2</code> sets the size of the PSII signal and trades off against the PSI weight, which the measured dark <code>Fv/Fm</code> bounds (<a href="/LeafPhotosynthesis.jl/dev/flexas_2002_water_stress.html#flexas-connectivity">connectivity and the dark level</a>). No parameter is fitted to the digitized points; the <a href="/LeafPhotosynthesis.jl/dev/flexas_2002_water_stress.html#flexas-chosen-inputs">walkthrough</a> lists the chosen inputs. See the <a href="./flexas_2002_water_stress.html">mathematical proof, diagnostics and model comparison</a>.</p><h2 id="gallery-gu-2019" tabindex="-1">Gu et al. (2019) lake-model fluorescence <a class="header-anchor" href="#gallery-gu-2019" aria-label="Permalink to &quot;Gu et al. (2019) lake-model fluorescence {#gallery-gu-2019}&quot;">​</a></h2><p>Evaluate the PSII lake-model relations of Gu et al. (2019, <em>New Phytologist</em> 223:1179–1191) between fluorescence, the open reaction-center fraction <code>qL</code>, <code>NPQ</code> and linear electron flow (<code>LakeModelFluorescence</code>): their <em>Vitis vinifera</em> light response (Figs. 1c and 4c), the fluorescence-to-assimilation curves of Fig. 2a, and the Flexas et al. (2002) Figure 2 beside <code>CytochromeFluorescence</code>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/gu_2019.jl</span></span></code></pre></div><div class="leaf-app"><details class="source"><summary>Read the complete Gu et al. (2019) example</summary><pre><code data-source="gu_2019"></code></pre></details><div id="gu-plots" class="plot-grid"></div></div><p>The relations reproduce the paper&#39;s <code>ΦPSII</code> and Fig. 2a; its plotted <code>ΦSIF</code>, as digitized, is 26–33 % above its own Eq. 14. They do not predict <code>qL</code> or <code>NPQ</code>: closed with the open fraction of the Cytochrome b₆f model in a lake antenna, or with one transferred measured <code>qL(PAR)</code>, they miss the Flexas curves (<code>Fs / Fo</code> RMSE <code>0.24</code> and <code>0.43</code> against <code>0.062</code> for <code>CytochromeFluorescence</code>, all through the same PAM observer). See the <a href="./lake_model_fluorescence.html">walkthrough</a>.</p><h2 id="gallery-reproduce" tabindex="-1">Change a parameter, rebuild the figures <a class="header-anchor" href="#gallery-reproduce" aria-label="Permalink to &quot;Change a parameter, rebuild the figures {#gallery-reproduce}&quot;">​</a></h2><p>Edit the named values in <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/parameters/bonan_11_1.toml" target="_blank" rel="noreferrer">bonan_11_1.toml</a>, <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/parameters/core_exchange.toml" target="_blank" rel="noreferrer">core_exchange.toml</a>, or the CO₂ sweep in <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/parameters/turnover.toml" target="_blank" rel="noreferrer">turnover.toml</a>, then rebuild the documentation. The build runs every example in both precisions, checks the results and writes the chart data and CSV tables:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/make.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bind</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/build/1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Then open <code>http://127.0.0.1:8000/</code>. Chart.js, KaTeX and all model results are served from the site itself; no network access is needed to view the charts. Try changing <code>opening_timescale</code> while keeping <code>closing_timescale</code> fixed. Which part of the response changes? Then change the Ball–Berry slope and compare the new equilibrium.</p><p>TOML parsing is isolated in <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/setup/read_parameters.jl" target="_blank" rel="noreferrer">read_parameters.jl</a>; explicit component assembly lives in <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/setup/bonan_leaf.jl" target="_blank" rel="noreferrer">bonan_leaf.jl</a> and <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/setup/core_leaf.jl" target="_blank" rel="noreferrer">core_leaf.jl</a>; output formatting lives in <a href="https://github.com/RSFraLab/LeafPhotosynthesis.jl/blob/main/examples/setup/write_tables.jl" target="_blank" rel="noreferrer">write_tables.jl</a>. Bonan 11.1 has independent high-precision equation checks, but no executed MATLAB comparison yet. The equilibrium and stomatal examples use illustrative settings; they are not reproductions of Bonan 12.1 or a fit to observed time courses.</p>`,61))])}const f=i(d,[["render",h]]);export{k as __pageData,f as default};
